"use client";

import * as React from "react";
import { X } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * DIFF REVIEW: accept or reject what the AI changed
 *
 *   pending   the change inline: removed words struck in red,
 *             added words in green; Reject and Accept
 *   accepted  the text resolves in place: removed words shrink
 *             out of the sentence and added ones lose their
 *             green; Accept morphs to "Accepted" as its check
 *             draws itself, Reject folds away, Undo opens in
 *   rejected  the same in reverse: the added words shrink away
 *             and the struck ones come back as plain text
 *
 * The header count rolls ("3 to review" → "2 of 3 accepted").
 * Give it before and after; it works out the difference by word
 * (prose) or by line (code). Accept or reject one at a time, or
 * all at once. Works controlled or on its own; onComplete fires
 * when nothing is left to review.
 * ───────────────────────────────────────────────────────── */

export type ChangeDecision = "pending" | "accepted" | "rejected";

export interface DiffChange {
  id: string;
  before: string;
  after: string;
  /** Where it is, e.g. "Paragraph 2" or a file name. */
  label?: string;
}

export interface DiffReviewProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  changes: DiffChange[];
  /** Compare word by word (prose) or line by line (code). */
  mode?: "words" | "lines";
  decisions?: Record<string, ChangeDecision>;
  defaultDecisions?: Record<string, ChangeDecision>;
  /** Every decision after a change (one call for Accept all). */
  onDecisionsChange?: (decisions: Record<string, ChangeDecision>) => void;
  onDecisionChange?: (id: string, decision: ChangeDecision) => void;
  /** Called when the last pending change gets a decision. */
  onComplete?: (decisions: Record<string, ChangeDecision>) => void;
  /** Show the decisions without Undo, e.g. once they've been sent. */
  readOnly?: boolean;
  title?: string;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const SMALL = `inline-flex h-7 items-center gap-1 rounded-full px-2.5 text-[12px] font-medium transition-colors ${FOCUS}`;
const MORPH = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 420ms ${MORPH}, opacity ${show ? "300ms" : "160ms"} ${MORPH}, filter 300ms ${MORPH}`,
      }}
    >
      <span className="flex min-w-0 items-center overflow-hidden whitespace-nowrap [clip-path:inset(-4px)]">
        {children}
      </span>
    </span>
  );
}

function DrawnCheck({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${MORPH} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

type Op = { kind: "same" | "add" | "remove"; text: string };

/** Longest-common-subsequence diff over tokens; falls back to a full replace for very large inputs. */
function diff(a: string[], b: string[]): Op[] {
  if (a.length * b.length > 250_000) {
    return [
      ...a.map((text) => ({ kind: "remove" as const, text })),
      ...b.map((text) => ({ kind: "add" as const, text })),
    ];
  }
  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint32Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);
  const ops: Op[] = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      ops.push({ kind: "same", text: a[i] });
      i++;
      j++;
    } else if (dp[i + 1][j] >= dp[i][j + 1])
      ops.push({ kind: "remove", text: a[i++] });
    else ops.push({ kind: "add", text: b[j++] });
  }
  while (i < a.length) ops.push({ kind: "remove", text: a[i++] });
  while (j < b.length) ops.push({ kind: "add", text: b[j++] });
  return ops;
}

type Run =
  | { kind: "same"; tokens: string[] }
  | { kind: "change"; removed: string[]; added: string[] };

/** Group ops into unchanged runs and change runs (everything removed, then everything added). */
function toRuns(ops: Op[]): Run[] {
  const runs: Run[] = [];
  for (const op of ops) {
    const last = runs[runs.length - 1];
    if (op.kind === "same") {
      if (last?.kind === "same") last.tokens.push(op.text);
      else runs.push({ kind: "same", tokens: [op.text] });
    } else {
      let run = last;
      if (run?.kind !== "change") {
        run = { kind: "change", removed: [], added: [] };
        runs.push(run);
      }
      (op.kind === "remove" ? run.removed : run.added).push(op.text);
    }
  }
  return runs;
}

/** Fold short unchanged bits ("to", a space) between two changes into them, so a rewrite reads as one phrase. */
function absorbSmall(runs: Run[]): Run[] {
  const out: Run[] = [];
  for (let i = 0; i < runs.length; i++) {
    const run = runs[i];
    const prev = out[out.length - 1];
    const next = runs[i + 1];
    if (
      run.kind === "same" &&
      prev?.kind === "change" &&
      next?.kind === "change" &&
      run.tokens.join("").trim().length <= 3
    ) {
      prev.removed.push(...run.tokens, ...next.removed);
      prev.added.push(...run.tokens, ...next.added);
      i++;
    } else if (run.kind === "change" && prev?.kind === "change") {
      prev.removed.push(...run.removed);
      prev.added.push(...run.added);
    } else
      out.push(
        run.kind === "same"
          ? { kind: "same", tokens: [...run.tokens] }
          : {
              kind: "change",
              removed: [...run.removed],
              added: [...run.added],
            },
      );
  }
  return out;
}

const words = (s: string) => s.split(/(\s+|[.,;:!?()"“”])/).filter(Boolean);
const lines = (s: string) => s.split("\n");

/** Words that leave shrink out of the sentence (their font size eases to nothing, so the line closes up around them). */
const gone = (out: boolean, reduced: boolean): React.CSSProperties => ({
  fontSize: out ? 0 : undefined,
  opacity: out ? 0 : 1,
  transition: reduced
    ? "none"
    : `font-size 460ms ${MORPH}, opacity 220ms ${MORPH}, background-color 300ms, color 300ms, text-decoration-color 300ms, margin 460ms ${MORPH}`,
});

function InlineDiff({
  before,
  after,
  decision,
  reduced,
}: {
  before: string;
  after: string;
  decision: ChangeDecision;
  reduced: boolean;
}) {
  const runs = React.useMemo(
    () => absorbSmall(toRuns(diff(words(before), words(after)))),
    [before, after],
  );
  const pending = decision === "pending";
  return (
    <p
      className={`text-[13.5px] leading-relaxed transition-colors duration-300 ${decision === "rejected" ? "text-muted-foreground" : "text-foreground"}`}
    >
      {runs.map((run, i) =>
        run.kind === "same" ? (
          <React.Fragment key={i}>{run.tokens.join("")}</React.Fragment>
        ) : (
          <React.Fragment key={i}>
            {run.removed.length > 0 && (
              <del
                aria-hidden={decision === "accepted" || undefined}
                className={`rounded-[3px] ${pending ? "bg-red-500/10 text-red-600 decoration-red-500/50 dark:text-red-400" : "bg-transparent text-inherit decoration-transparent no-underline"}`}
                style={gone(decision === "accepted", reduced)}
              >
                {run.removed.join("")}
              </del>
            )}
            {run.added.length > 0 && (
              <ins
                aria-hidden={decision === "rejected" || undefined}
                className={`rounded-[3px] no-underline ${pending ? "bg-emerald-500/15 text-emerald-700 dark:text-emerald-400" : "bg-transparent text-inherit"}`}
                style={{
                  ...gone(decision === "rejected", reduced),
                  marginLeft: pending && run.removed.length > 0 ? 2 : 0,
                }}
              >
                {run.added.join("")}
              </ins>
            )}
          </React.Fragment>
        ),
      )}
    </p>
  );
}

function LineDiff({
  before,
  after,
  decision,
  reduced,
}: {
  before: string;
  after: string;
  decision: ChangeDecision;
  reduced: boolean;
}) {
  const ops = React.useMemo(
    () =>
      toRuns(diff(lines(before), lines(after))).flatMap((run): Op[] =>
        run.kind === "same"
          ? run.tokens.map((text) => ({ kind: "same", text }))
          : [
              ...run.removed.map((text) => ({ kind: "remove" as const, text })),
              ...run.added.map((text) => ({ kind: "add" as const, text })),
            ],
      ),
    [before, after],
  );
  const pending = decision === "pending";
  return (
    <pre
      className={`overflow-x-auto font-mono text-[12px] leading-5 transition-colors duration-300 ${decision === "rejected" ? "text-muted-foreground" : "text-foreground"}`}
    >
      {ops.map((op, i) => {
        // Lines that don't survive the decision fold shut; the ones that do lose their tint and gutter.
        const out =
          (op.kind === "remove" && decision === "accepted") ||
          (op.kind === "add" && decision === "rejected");
        const tint = pending && op.kind !== "same";
        return (
          <span
            key={i}
            aria-hidden={out || undefined}
            className="grid"
            style={{
              gridTemplateRows: out ? "0fr" : "1fr",
              opacity: out ? 0 : 1,
              transition: reduced
                ? "none"
                : `grid-template-rows 420ms ${MORPH}, opacity 200ms ${MORPH}`,
            }}
          >
            <span
              className={`flex min-h-0 overflow-hidden transition-colors duration-300 ${
                tint
                  ? op.kind === "add"
                    ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400"
                    : "bg-red-500/10 text-red-600 dark:text-red-400"
                  : ""
              }`}
            >
              <span
                aria-hidden="true"
                className="w-5 shrink-0 select-none pl-1.5 text-muted-foreground transition-opacity duration-300"
                style={{ opacity: tint ? 1 : 0 }}
              >
                {op.kind === "add" ? "+" : op.kind === "remove" ? "−" : " "}
              </span>
              <span className="pr-3">{op.text || " "}</span>
              {pending && (
                <span className="sr-only">
                  {op.kind === "add"
                    ? " (added)"
                    : op.kind === "remove"
                      ? " (removed)"
                      : ""}
                </span>
              )}
            </span>
          </span>
        );
      })}
    </pre>
  );
}

export function DiffReview({
  changes,
  mode = "words",
  decisions,
  defaultDecisions = {},
  onDecisionsChange,
  onDecisionChange,
  onComplete,
  readOnly = false,
  title = "Suggested changes",
  className = "",
  ...props
}: DiffReviewProps) {
  const reduced = useReducedMotion();
  const [own, setOwn] =
    React.useState<Record<string, ChangeDecision>>(defaultDecisions);
  const current = decisions ?? own;
  // Where focus goes after a decision: the button that just folded away hands it to the one that took its place.
  const buttons = React.useRef(new Map<string, HTMLButtonElement | null>());
  const focusNext = React.useRef<string | null>(null);
  React.useLayoutEffect(() => {
    if (!focusNext.current) return;
    buttons.current.get(focusNext.current)?.focus({ preventScroll: true });
    focusNext.current = null;
  });
  const registerButton = React.useCallback(
    (key: string, el: HTMLButtonElement | null) => {
      buttons.current.set(key, el);
    },
    [],
  );
  const decisionOf = (id: string) => current[id] ?? "pending";

  const commit = (ids: string[], decision: ChangeDecision) => {
    const next = {
      ...current,
      ...Object.fromEntries(ids.map((id) => [id, decision])),
    };
    if (decisions === undefined) setOwn(next);
    onDecisionsChange?.(next);
    ids.forEach((id) => onDecisionChange?.(id, decision));
    if (
      decision !== "pending" &&
      changes.every((c) => (next[c.id] ?? "pending") !== "pending")
    )
      onComplete?.(next);
  };
  const decide = (id: string, decision: ChangeDecision) => {
    const hadFocus = [...buttons.current.entries()].some(
      ([key, el]) => key.startsWith(`${id}:`) && el === document.activeElement,
    );
    if (hadFocus)
      focusNext.current =
        decision === "pending"
          ? `${id}:${decisionOf(id) === "rejected" ? "reject" : "accept"}`
          : `${id}:undo`;
    commit([id], decision);
  };
  const decideAll = (decision: ChangeDecision) =>
    commit(
      changes.filter((c) => decisionOf(c.id) === "pending").map((c) => c.id),
      decision,
    );

  const pending = changes.filter((c) => decisionOf(c.id) === "pending").length;
  const accepted = changes.filter(
    (c) => decisionOf(c.id) === "accepted",
  ).length;

  return (
    <div className={`w-full ${className}`} {...props}>
      <div className="mb-3 flex min-h-7 flex-wrap items-center justify-between gap-2">
        <p className="flex items-baseline gap-[0.3em] text-[13px] font-medium text-foreground">
          {title}
          {/* "3 to review" → "2 of 3 accepted": the count rolls and the words morph. */}
          <span
            aria-hidden="true"
            className="inline-flex items-baseline font-normal tabular-nums text-muted-foreground"
          >
            <NumberRoll
              value={pending > 0 ? pending : accepted}
              duration={600}
            />
            <Reveal show={pending === 0} reduced={reduced}>
              &nbsp;of&nbsp;
              <NumberRoll value={changes.length} duration={600} />
            </Reveal>
            &nbsp;
            <TextMorph>{pending > 0 ? "to review" : "accepted"}</TextMorph>
          </span>
          <span role="status" aria-live="polite" className="sr-only">
            {pending > 0
              ? `${pending} to review`
              : `${accepted} of ${changes.length} accepted`}
          </span>
        </p>
        {!readOnly && (
          <Reveal show={pending > 1} reduced={reduced}>
            <span className="flex gap-1 p-0.5">
              <button
                type="button"
                inert={pending < 2}
                onClick={() => decideAll("rejected")}
                className={`cursor-pointer ${SMALL} text-muted-foreground hover:bg-accent hover:text-foreground`}
              >
                Reject all
              </button>
              <button
                type="button"
                inert={pending < 2}
                onClick={() => decideAll("accepted")}
                className={`cursor-pointer ${SMALL} bg-primary text-primary-foreground hover:bg-primary/90`}
              >
                Accept all
              </button>
            </span>
          </Reveal>
        )}
      </div>

      <ul className="flex flex-col gap-2">
        {changes.map((change) => {
          const decision = decisionOf(change.id);
          const open = decision === "pending" && !readOnly;
          const name = change.label ?? "change";
          return (
            <li
              key={change.id}
              className={`overflow-hidden rounded-xl border transition-colors duration-300 ${decision === "pending" ? "border-border" : "border-border/60"}`}
            >
              <div className="flex min-h-10 items-center justify-between gap-3 border-b border-border/60 py-1 pl-3 pr-1.5">
                <span className="truncate text-[11.5px] text-muted-foreground">
                  {change.label ?? "Change"}
                </span>
                {/* The button you press becomes the answer: "Accept" morphs to "Accepted" while the other folds away. */}
                <span className="flex shrink-0 items-center">
                  <Reveal
                    show={decision === "rejected" || open}
                    reduced={reduced}
                  >
                    <span className="block p-0.5">
                      <button
                        ref={(el) => registerButton(`${change.id}:reject`, el)}
                        type="button"
                        inert={!open}
                        aria-label={`Reject ${name}`}
                        onClick={() => decide(change.id, "rejected")}
                        className={`cursor-pointer ${SMALL} ${open ? "text-muted-foreground hover:bg-accent hover:text-foreground" : "text-muted-foreground"}`}
                      >
                        <X aria-hidden="true" className="size-3.5" />
                        <TextMorph>
                          {decision === "rejected" ? "Rejected" : "Reject"}
                        </TextMorph>
                      </button>
                    </span>
                  </Reveal>
                  <Reveal
                    show={decision === "accepted" || open}
                    reduced={reduced}
                  >
                    <span className="block p-0.5">
                      <button
                        ref={(el) => registerButton(`${change.id}:accept`, el)}
                        type="button"
                        inert={!open}
                        aria-label={`Accept ${name}`}
                        onClick={() => decide(change.id, "accepted")}
                        className={`cursor-pointer ${SMALL} ${open ? "text-foreground hover:bg-accent" : "text-emerald-600 dark:text-emerald-400"}`}
                      >
                        <span
                          aria-hidden="true"
                          className="relative flex size-3.5 items-center justify-center"
                        >
                          {/* The plain check fades as a green one draws itself over it. */}
                          <svg
                            viewBox="0 0 16 16"
                            fill="none"
                            className="absolute size-3.5"
                            style={{
                              opacity: open ? 1 : 0,
                              transition: reduced
                                ? "none"
                                : `opacity 200ms ${MORPH}`,
                            }}
                          >
                            <path
                              d="M3.5 8.5 6.5 11.5 12.5 4.5"
                              stroke="currentColor"
                              strokeWidth="1.8"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            />
                          </svg>
                          <span className="absolute inset-0 flex items-center justify-center">
                            <DrawnCheck
                              drawn={decision === "accepted"}
                              reduced={reduced}
                            />
                          </span>
                        </span>
                        <TextMorph>
                          {decision === "accepted" ? "Accepted" : "Accept"}
                        </TextMorph>
                      </button>
                    </span>
                  </Reveal>
                  {!readOnly && (
                    <Reveal show={decision !== "pending"} reduced={reduced}>
                      <span className="block p-0.5 pl-1.5">
                        <button
                          ref={(el) => registerButton(`${change.id}:undo`, el)}
                          type="button"
                          inert={decision === "pending"}
                          onClick={() => decide(change.id, "pending")}
                          className={`cursor-pointer rounded px-1 text-[12px] font-medium text-foreground underline decoration-border underline-offset-2 hover:decoration-foreground ${FOCUS}`}
                        >
                          Undo
                        </button>
                      </span>
                    </Reveal>
                  )}
                </span>
              </div>
              <div className={mode === "lines" ? "py-2" : "px-3 py-2.5"}>
                {mode === "lines" ? (
                  <LineDiff
                    before={change.before}
                    after={change.after}
                    decision={decision}
                    reduced={reduced}
                  />
                ) : (
                  <InlineDiff
                    before={change.before}
                    after={change.after}
                    decision={decision}
                    reduced={reduced}
                  />
                )}
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

